const days = ['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'];
const today = days[new Date().getDay()];
return [{ json: { today, user_id: 1, check_time: new Date().toISOString() } }];

const plan = $input.first().json?.data || [];
const today = $('Get Today').first().json.today;
if (plan.length === 0) {
  return [{ json: { reminder: false, message: 'Rest day today - ' + today, exercises: [] } }];
}
const exercises = plan.map(p => p.exercise + ' (' + p.sets + 'x' + p.reps + ')').join(', ');
return [{ json: { reminder: true, day: today, exercise_count: plan.length, exercises_list: exercises, message: 'Time to workout! ' + plan.length + ' exercises planned for ' + today + ': ' + exercises, sent_at: new Date().toISOString() } }];
